+            Err(ExecutionError::Failed { message: "prime".into(), retryable: false })
+        });
+        for _ in 0..THRESHOLD { let _ = breaker.call(&fail, 0.0).await; }
+        assert_eq!(breaker.phase(), BreakerPhase::Open);
+        tokio::time::sleep(Duration::from_millis(2)).await;
+        assert_eq!(breaker.phase(), BreakerPhase::HalfOpen);
+
+        let invocations = Arc::new(AtomicU32::new(0));
+        let gate = Arc::new(tokio::sync::Barrier::new(usize::try_from(THRESHOLD).unwrap() + 1));
+        let mut joins = Vec::new();
+        for _ in 0..THRESHOLD {
+            let breaker = Arc::clone(&breaker);
+            let invocations = Arc::clone(&invocations);
+            let gate = Arc::clone(&gate);
+            joins.push(tokio::spawn(async move {
+                let step = step_fn(move |_| {
+                    let invocations = Arc::clone(&invocations);
+                    async move {
+                        let n = invocations.fetch_add(1, Ordering::SeqCst);
+                        if n == 0 { Ok(()) } else {
+                            Err(ExecutionError::Failed { message: "post-success".into(), retryable: false })
+                        }
+                    }
+                });
+                gate.wait().await;
+                breaker.call(&step, 0.0).await
+            }));
+        }
+        gate.wait().await;
+        for join in joins { let _ = join.await.unwrap(); }
+        if breaker.phase() == BreakerPhase::Open {
+            println!("reproduced trial={trial} invocations={} phase={:?}", invocations.load(Ordering::SeqCst), breaker.phase());
+            return;
+        }
+    }
+    println!("not reproduced in {TRIALS} trials");
+}
